def get_recommendation_for_category(category: str) -> Dict[str, Any]:
    """Retrieve default recommendations for a given category."""
    base = CATEGORY_BASE_RECOMMENDATIONS.get(
        category,
        CATEGORY_BASE_RECOMMENDATIONS["Application"]
    )
    return {
        "category": category,
        "title": base["title"],
        "possible_causes": base["causes"],
        "recommended_solutions": base["solutions"],
        "disclaimer": DISCLAIMER_TEXT
    }


def get_recommendation_for_error(category: str, message: str) -> Dict[str, Any]:
    """
    Generate targeted recommendation for a specific error record,
    checking specific signatures and falling back to category rules.
    """
    base = get_recommendation_for_category(category)
    msg_lower = (message or "").lower()

    specific_cause = None
    specific_solution = None

    for rule in SPECIFIC_SIGNATURE_RULES:
        if any(kw in msg_lower for kw in rule["keywords"]):
            specific_cause = rule["cause"]
            specific_solution = rule["solution"]
            break

    causes = list(base["possible_causes"])
    solutions = list(base["recommended_solutions"])

    if specific_cause and specific_solution:
        causes.insert(0, f"Specific Indicator: {specific_cause}")
        solutions.insert(0, f"Specific Action: {specific_solution}")

    return {
        "category": category,
        "title": base["title"],
        "possible_causes": causes,
        "recommended_solutions": solutions,
        "disclaimer": DISCLAIMER_TEXT
    }
